import 'package:flutter/foundation.dart';

/// AI分析の口調
enum AnalysisTone {
  gentle,   // やさしい
  neutral,  // 標準
  strict,   // やや厳しめ
  coach,    // 熱血コーチ
  clinical, // 医療従事者向け・専門的
}

